{"command":"python3 - << 'PY'
import subprocess, time
def start(args, w=80,h=24):
    subprocess.run(["tmux","kill-server"], stderr=subprocess.DEVNULL); time.sleep(0.15)
    subprocess.run(["tmux","new-session","-d","-s","t","-x",str(w),"-y",str(h), args]); time.sleep(0.5)
def cap(label=""):
    r=subprocess.run(["tmux","capture-pane","-t","t","-p"], capture_output=True, text=True)
    print(f"=== {label} ===")
    for i,line in enumerate(r.stdout.splitlines()):
        if line.strip(): print(f"{i:02d}:{line!r}")
    alive = subprocess.run(["tmux","list-panes","-t","t"],capture_output=True,text=True).returncode==0
    print("alive",alive)
def send(s): subprocess.run(["tmux","send-keys","-t","t","-l",s]); time.sleep(0.4)
def key(k): subprocess.run(["tmux","send-keys","-t","t",k]); time.sleep(0.4)

for finalkey in ["r","n","Escape","x","C-c"]:
    start('./executable -p "ab"')
    send("ab"); cap(f"completed before {finalkey}")
    if finalkey=="Escape": key("Escape")
    elif finalkey=="C-c": key("C-c")
    else: send(finalkey)
    cap(f"after {finalkey}")

# left/right mid test custom prompt
start('./executable -p "hello world"')
send("he"); key("Left"); cap("after Left mid (custom)")
key("Right"); cap("after Right mid (custom)")
# left/right with generated prompt
start('./executable -w 5')
cap("generated initial")
send("a") # likely wrong char
key("Left"); cap("after Left generated")
key("Right"); cap("after Right generated")
PY"}

