import subprocess, time
def lines_for(txt,w,h=24):
    subprocess.run(["tmux","kill-server"], stderr=subprocess.DEVNULL); time.sleep(0.08)
    subprocess.run(["tmux","new-session","-d","-s","t","-x",str(w),"-y",str(h), f'./executable -p "{txt}"']); time.sleep(0.25)
    r=subprocess.run(["tmux","capture-pane","-t","t","-p"], capture_output=True, text=True)
    return [l for l in r.stdout.splitlines() if l.strip()]
for W in [80,100,40,50,60,81,79]:
    # find max n with 1 line
    lo=None
    for n in range(1, W+20):
        ls=lines_for("x"*n,W)
        if len(ls)!=1:
            lo=n; break
    print(f"W={W} first_wrap_n={lo} lines={ [len(l.strip()) for l in lines_for('x'*(lo or 1),W)] }")
PY"}

