    subprocess.run(["tmux","kill-server"], stderr=subprocess.DEVNULL); time.sleep(0.05)
    subprocess.run(["tmux","new-session","-d","-s","t","-x",str(w),"-y","24", f'./executable -p "{txt}"']); time.sleep(0.2)
