import subprocess, time, os, shutil
def start(args,w=80,h=24):
    subprocess.run(["tmux","kill-server"], stderr=subprocess.DEVNULL); time.sleep(0.12)
    subprocess.run(["tmux","new-session","-d","-s","t","-x",str(w),"-y",str(h), args]); time.sleep(0.45)
def cap(label=""):
    r=subprocess.run(["tmux","capture-pane","-t","t","-p"], capture_output=True, text=True)
    print(f"=== {label} ===")
    for i,line in enumerate(r.stdout.splitlines()):
        if line.strip(): print(f"{i:02d}:{line.rstrip()!r}")
    if os.path.exists("/home/agent/.config/thokr/log.csv"):
        print("LOG:",open("/home/agent/.config/thokr/log.csv").read())
def send(s): subprocess.run(["tmux","send-keys","-t","t","-l",s]); time.sleep(0.35)
def key(k): subprocess.run(["tmux","send-keys","-t","t",k]); time.sleep(0.35)

def fresh(prompt, seq_label, actions):
    shutil.rmtree("/home/agent/.config/thokr", ignore_errors=True)
    start(f'./executable -p "{prompt}"')
    for a in actions:
        if a=="BS": key("BSpace")
        else: send(a)
    cap(seq_label)

fresh("hello", "all wrong 'xxxxx'", ["xxxxx"])
fresh("hello", "1 wrong then correct rest 'xello'", ["xello"])
fresh("hello", "wrong, backspace, correct", ["x","BS","hello"])
fresh("hello", "wrong, backspace x2 cannot? ", ["hx","BS","BS","BS","hello"])
fresh("hello world", "extra chars beyond? type 'hello world!'", ["hello world!"])
fresh("ab", "backspace at start then ab", ["BS","ab"])
fresh("ab", "type a, backspace, b (wrong for a), wrong etc", ["a","BS","b"])
# accuracy with spaces wrong
fresh("a b", " 'axb' (x for space)", ["axb"])
fresh("a b", " 'aXb' etc", ["aXb"])
