{"command":"cat > /tmp/collect.py <<'PY'
import pty, os, time, select, fcntl, termios, struct, sys, re, signal

def get_screen(args, rows=24, cols=200, wait=0.3):
    pid, fd = pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm-256color"; os.environ["HOME"]="/tmp/fhcollect"; os.environ.pop("XDG_CONFIG_HOME",None)
        os.execv(args[0], args)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH",rows,cols,0,0))
    data=b""
    end=time.time()+wait
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.02)
        if r:
            try: d=os.read(fd,65536)
            except: break
            if d:
                data+=d
                if b'?25l' in data:
                    break
    try: os.kill(pid,9); os.waitpid(pid,0)
    except: pass
    # parse grid
    grid=[[" "]*cols for _ in range(rows)]
    txt=data.decode('utf-8',errors='ignore')
    i=0; r=0; c=0
    while i<len(txt):
        ch=txt[i]
        if ch=='\x1b':
            m=re.match(r'\x1b\[([0-9;?]*)([A-Za-z])', txt[i:])
            if m:
                params=m.group(1); cmd=m.group(2)
                if cmd=='H':
                    parts=params.split(';') if params else []
                    if len(parts)>=2 and parts[0] and parts[1]:
                        r=int(parts[0])-1; c=int(parts[1])-1
                    elif len(parts)==1 and parts[0]:
                        r=int(parts[0])-1; c=0
                    else:
                        r=0;c=0
                i+=len(m.group(0)); continue
            else:
                i+=1; continue
        elif ch=='\r': c=0; i+=1; continue
        elif ch=='\n': r+=1; c=0; i+=1; continue
        else:
            if 0<=r<rows and 0<=c<cols:
                grid[r][c]=ch
            c+=1; i+=1; continue
    return ["".join(row).rstrip() for row in grid]

if __name__=="__main__":
    args=sys.argv[1:]
    for line in get_screen(["./executable"]+args):
        if line.strip(): print(repr(line))
