import pty, os, time, select, fcntl, termios, struct, sys, re, signal

def get_screen(args, rows=24, cols=80, wait=0.5):
    pid, fd = pty.fork()
    if pid==0:
        fcntl.ioctl(1, termios.TIOCSWINSZ, struct.pack("HHHH",rows,cols,0,0))
        os.environ["TERM"]="xterm-256color"; os.environ["HOME"]="/tmp/fhcollect"; os.environ.pop("XDG_CONFIG_HOME",None)
        os.execv(args[0], args)
    data=b""
    end=time.time()+wait
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.02)
        if r:
            try: d=os.read(fd,65536)
