// ------- suggestions (Jaro-Winkler) -------
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a == b { return 1.0; }
    let (la, lb) = (a.len(), b.len());
    if la == 0 || lb == 0 { return 0.0; }
    let search = (la.max(lb) / 2).saturating_sub(1);
    let mut a_match = vec![false; la];
    let mut b_match = vec![false; lb];
    let mut matches = 0usize;
    for i in 0..la {
        let lo = i.saturating_sub(search);
        let hi = (i + search + 1).min(lb);
        for j in lo..hi {
            if !b_match[j] && a[i] == b[j] { a_match[i] = true; b_match[j] = true; matches += 1; break; }
        }
    }
    if matches == 0 { return 0.0; }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..la {
        if a_match[i] {
            while !b_match[k] { k += 1; }
            if a[i] != b[k] { t += 1; }
            k += 1;
        }
    }
    let t = t / 2;
    let m = matches as f64;
    (m / la as f64 + m / lb as f64 + (m - t as f64) / m) / 3.0
}
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let mut p = 0usize;
        for (x, yv) in a.chars().zip(b.chars()) {
            if x == yv { p += 1; } else { break; }
            if p == 4 { break; }
        }
        j + (p as f64 * 0.1 * (1.0 - j))
    } else { j }
}
fn did_you_mean(input: &str, candidates: &[&str]) -> Option<String> {
    let mut best: Option<(f64, String)> = None;
    for cand in candidates {
        let conf = jaro_winkler(input, cand);
        if conf > 0.8 && (best.is_none() || conf > best.as_ref().unwrap().0) {
            best = Some((conf, cand.to_string()));
        }
    }
    best.map(|(_, s)| s)
}
fn did_you_mean_def(input: &str) -> Option<OptDef> {
    let names: Vec<&str> = ALL.iter().map(|d| d.long).collect();
