// ------- error constructors -------
struct Ctx { bin: String, colour: bool }

impl Ctx {
    fn footer(&self) -> String { format!("For more information try {}", g("--help", self.colour)) }
    fn usage_line(&self, specs: &[String]) -> String {
        if specs.is_empty() { format!("    {} [OPTIONS]", self.bin) } else { format!("    {} {}", self.bin, specs.join(" ")) }
    }
    fn emit(&self, msg: String) -> ParseResult {
        eprint!("{}", msg);
        let _ = std::io::stderr().flush();
        ParseResult::Exit(2)
    }
    fn unknown(&self, arg: &str, long_ctx: Option<(Option<OptDef>, Vec<OptDef>)>) -> ParseResult {
        // long_ctx: Some((suggestion, used)) for long errors; None for short/positional
        let mut msg = format!("{} Found argument '{}' which wasn't expected, or isn't valid in this context\n", err_head(self.colour), y(arg, self.colour));
        let usage_specs: Vec<String>;
        match &long_ctx {
            Some((sugg, used)) => {
                if let Some(s) = sugg {
                    msg.push_str(&format!("\n\tDid you mean '{}'?\n", g(&format!("--{}", s.long), self.colour)));
                }
                if arg.starts_with('-') {
                    msg.push_str(&format!("\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n", arg, arg));
                }
                let mut specs: Vec<String> = used.iter().map(|d| d.spec()).collect();
                if let Some(s) = sugg {
                    let sp = s.spec();
                    if !specs.contains(&sp) { specs.push(sp); }
                }
                usage_specs = specs;
            }
            None => {
                if arg.starts_with('-') {
                    msg.push_str(&format!("\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n", arg, arg));
                }
                usage_specs = vec![];
            }
        }
        msg.push_str(&format!("\nUSAGE:\n{}\n\n{}\n", self.usage_line(&usage_specs), self.footer()));
        self.emit(msg)
    }
    fn missing(&self, def: OptDef) -> ParseResult {
        let mut msg = format!("{} The argument '{}' requires a value but none was supplied\n", err_head(self.colour), y(&def.spec(), self.colour));
        if def.id == OptId::Lang {
            msg.push_str("\t[possible values: english, english1k, english10k]\n");
        }
        msg.push_str(&format!("\nUSAGE:\n    {} [OPTIONS]\n\n{}\n", self.bin, self.footer()));
        self.emit(msg)
    }
    fn duplicate(&self, def: OptDef) -> ParseResult {
        let msg = format!("{} The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} [OPTIONS]\n\n{}\n", err_head(self.colour), y(&def.spec(), self.colour), self.bin, self.footer());
        self.emit(msg)
    }
    fn invalid_numeric(&self, def: OptDef, value: &str, reason: &str) -> ParseResult {
        let msg = format!("{} Invalid value {} for '{}': {}\n\n{}\n", err_head(self.colour), y(&format!("\"{}\"", value), self.colour), y(&def.spec(), self.colour), reason, self.footer());
        self.emit(msg)
    }
    fn invalid_lang(&self, value: &str, used: &[OptDef]) -> ParseResult {
        let sugg = did_you_mean(value, &["english", "english1k", "english10k"]);
        let possible = format!("[possible values: {}, {}, {}]", g("english", self.colour), g("english1k", self.colour), g("english10k", self.colour));
        let mut msg = format!("{} \"{}\" isn't a valid value for '{}'\n\t{}\n", err_head(self.colour), value, y(&LANG.spec(), self.colour), possible);
        if let Some(s) = &sugg {
            msg.push_str(&format!("\n\tDid you mean {}?\n", g(&format!("\"{}\"", s), self.colour)));
        }
        let specs: Vec<String> = used.iter().map(|d| d.spec()).collect();
        msg.push_str(&format!("\nUSAGE:\n{}\n\n{}\n", self.usage_line(&specs), self.footer()));
        self.emit(msg)
    }
    fn too_many_values(&self, def: OptDef, value: &str, used: &[OptDef]) -> ParseResult {
        let specs: Vec<String> = used.iter().map(|d| d.spec()).collect();
        let line = if specs.is_empty() { format!("{} [OPTIONS]", self.bin) } else { format!("{} {}", self.bin, specs.join(" ")) };
        let msg = format!("{} The value '{}' was provided to '{}' but it wasn't expecting any more values\n\n{}\n\n{}\n", err_head(self.colour), y(value, self.colour), y(&format!("--{}", def.long), self.colour), line, self.footer());
        self.emit(msg)
    }
    fn invalid_utf8(&self) -> ParseResult {
        let msg = format!("{} Invalid UTF-8 was detected in one or more arguments\n\nUSAGE:\n    {} [OPTIONS]\n\n{}\n", err_head(self.colour), self.bin, self.footer());
        self.emit(msg)
    }
}

pub enum ParseResult {
    Run(Config),
    Exit(i32),
}

struct Occ { def: OptDef, value: Option<String> }

pub fn parse_args() -> ParseResult {
    let ctx = Ctx { bin: bin_name(), colour: colours_enabled(std::io::stderr().is_terminal()) };
    let help_ctx_colour = colours_enabled(std::io::stdout().is_terminal());
    let _ = help_ctx_colour;
    let argv: Vec<OsString> = env::args_os().skip(1).collect();
    let mut occs: Vec<Occ> = Vec::new();
    let mut used: Vec<OptDef> = Vec::new();
    let mut used_push = |used: &mut Vec<OptDef>, def: OptDef| {
        if !used.iter().any(|d| d.id == def.id) { used.push(def); }
    };
    let mut trailing_only = false;
    let mut trailing_missing: Option<OptDef> = None; // option left missing with no following non-separator token
    let mut i = 0usize;

    macro_rules! reg {
        ($def:expr) => {{
            let def = $def;
            if !used.iter().any(|d| d.id == def.id) { used.push(def); }
            def
        }};
    }

    while i < argv.len() {
        let tok_os = argv[i].clone();
        let tok = tok_os.to_string_lossy().into_owned();
        let tok_valid_utf8 = tok_os.to_str().is_some();

        if !trailing_only && tok == "--" {
            trailing_only = true;
            i += 1;
            continue;
        }

        if !trailing_only && tok.starts_with("--") && tok.len() > 2 {
            trailing_missing = None;
            let body = &tok[2..];
            let (name, eq_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            if name.is_empty() {
                return ctx.unknown("--", Some((None, used.clone())));
            }
            match by_long(name) {
                Some(def) if def.id == OptId::Help => {
                    if let Some(v) = eq_val {
                        return ctx.too_many_values(def, &format!("={}", v), &used);
                    }
                    print_help(&ctx.bin);
                    return ParseResult::Exit(0);
                }
                Some(def) if def.id == OptId::Version => {
                    if let Some(v) = eq_val {
                        return ctx.too_many_values(def, &format!("={}", v), &used);
                    }
                    print_version();
                    return ParseResult::Exit(0);
                }
                Some(def) => {
                    reg!(def);
                    if let Some(v) = eq_val {
                        if !tok_valid_utf8 { return ctx.invalid_utf8(); }
                        occs.push(Occ { def, value: Some(v) });
                    } else {
                        // need a separate value?
                        match peek_value(&argv, i) {
                            Peek::Value(j) => {
                                if argv[j].to_str().is_none() { return ctx.invalid_utf8(); }
                                let val = argv[j].to_string_lossy().into_owned();
                                occs.push(Occ { def, value: Some(val) });
                                i = j;
                            }
                            Peek::None => {
                                occs.push(Occ { def, value: None });
                                trailing_missing = Some(def);
                            }
                        }
                    }
                }
                None => {
                    let sugg = did_you_mean_def(name);
                    let arg = format!("--{}", name);
                    return ctx.unknown(&arg, Some((sugg, used.clone())));
                }
            }
            i += 1;
            continue;
        }

        if !trailing_only && tok.starts_with('-') && tok.len() > 1 {
            trailing_missing = None;
            // short cluster
            let cluster = &tok[1..];
            let mut consumed_next: Option<usize> = None;
            let mut handled = false;
            for (ci, ch) in cluster.char_indices() {
                match by_short(ch) {
                    Some(def) if def.id == OptId::Help => { print_help(&ctx.bin); return ParseResult::Exit(0); }
                    Some(def) if def.id == OptId::Version => { print_version(); return ParseResult::Exit(0); }
                    Some(def) => {
                        reg!(def);
                        let rest = &cluster[ci + ch.len_utf8()..];
                        if !rest.is_empty() {
                            let v = if let Some(stripped) = rest.strip_prefix('=') { stripped.to_string() } else { rest.to_string() };
                            if !tok_valid_utf8 { return ctx.invalid_utf8(); }
                            occs.push(Occ { def, value: Some(v) });
                        } else {
                            match peek_value(&argv, i) {
                                Peek::Value(j) => {
                                    if argv[j].to_str().is_none() { return ctx.invalid_utf8(); }
                                    let val = argv[j].to_string_lossy().into_owned();
                                    occs.push(Occ { def, value: Some(val) });
                                    consumed_next = Some(j);
                                }
                                Peek::None => {
                                    occs.push(Occ { def, value: None });
                                    trailing_missing = Some(def);
                                }
                            }
                        }
                        handled = true;
                        break;
                    }
                    None => {
                        let arg = format!("-{}", ch);
                        return ctx.unknown(&arg, None);
                    }
                }
            }
            let _ = handled;
            if let Some(j) = consumed_next { i = j; }
            i += 1;
            continue;
        }

        // positional
        let _ = tok_valid_utf8;
        return ctx.unknown(&tok, None);
    }

    // parse-end missing (only if its group has no values at all)
    if let Some(def) = trailing_missing {
        let has_value = occs.iter().any(|o| o.def.id == def.id && o.value.is_some());
        if !has_value {
            return ctx.missing(def);
        }
    }

    // validation in first-occurrence order
    for def in &used {
        let group: Vec<&Occ> = occs.iter().filter(|o| o.def.id == def.id).collect();
        let values: Vec<&String> = group.iter().filter_map(|o| o.value.as_ref()).collect();
        if values.is_empty() {
            return ctx.missing(*def);
        }
        for v in &values {
            match def.id {
                OptId::Lang => {
                    if !["english", "english1k", "english10k"].contains(&v.as_str()) {
                        return ctx.invalid_lang(v, &used);
                    }
                }
                OptId::Full | OptId::Secs | OptId::Words => {
                    if let Err(e) = v.parse::<u64>() {
                        return ctx.invalid_numeric(*def, v, &e.to_string());
                    }
                }
                _ => {}
            }
        }
        if group.len() > 1 {
            return ctx.duplicate(*def);
        }
    }

    let get = |id: OptId| -> Option<String> {
        occs.iter().find(|o| o.def.id == id).and_then(|o| o.value.clone())
    };
    let cfg = Config {
        full_sentences: get(OptId::Full).map(|v| v.parse::<u64>().unwrap()),
        language: get(OptId::Lang).unwrap_or_else(|| "english".to_string()),
        prompt: get(OptId::Prompt),
        number_of_secs: get(OptId::Secs).map(|v| v.parse::<u64>().unwrap()),
        number_of_words: get(OptId::Words).map(|v| v.parse::<u64>().unwrap()).unwrap_or(15),
    };
    ParseResult::Run(cfg)
}

enum Peek { Value(usize), None }

fn peek_value(argv: &[OsString], i: usize) -> Peek {
    if i + 1 >= argv.len() { return Peek::None; }
    let next = argv[i + 1].to_string_lossy().into_owned();
    if next == "--" { return Peek::None; }
    if next.starts_with('-') && next.len() > 1 { return Peek::None; }
    Peek::Value(i + 1)
}

pub fn stdin_tty_error() -> i32 {
    let ctx = Ctx { bin: "thokr".to_string(), colour: colours_enabled(std::io::stderr().is_terminal()) };
    let msg = format!("{} stdin must be a tty\n\nUSAGE:\n    thokr [OPTIONS]\n\n{}\n", err_head(ctx.colour), ctx.footer());
    eprint!("{}", msg);
    let _ = std::io::stderr().flush();
    2
}
RS"}

