fn choose<'a>(rng: &mut impl Rng, list: &'a [&'a str]) -> &'a str {
    list[rng.gen_range(0..list.len())]
}

fn modifier(rng: &mut impl Rng) -> String {
    match rng.gen_range(0..10) {
        0..=4 => choose(rng, ADJECTIVES).to_string(),
        5..=7 => choose(rng, COLORS).to_string(),
        _ => choose(rng, MATERIALS).to_string(),
    }
}

fn noun_phrase(rng: &mut impl Rng, with_article: Option<bool>) -> (Vec<String>, bool) {
    let mut toks = Vec::new();
    let article = with_article.unwrap_or_else(|| rng.gen_bool(0.72));
    if article {
        toks.push("the".to_string());
    }
    let mods = match rng.gen_range(0..10) {
        0..=2 => 0,
        3..=7 => 1,
        _ => 2,
    };
    for _ in 0..mods {
        toks.push(modifier(rng));
    }
    let plural = rng.gen_bool(0.45);
    let mut n = choose(rng, NOUNS).to_string();
    // nouns list contains a few verb-like entries; pluralise naively
    if plural {
        n.push('s');
    }
    toks.push(n);
    (toks, plural)
}

fn generate_sentence(rng: &mut impl Rng) -> String {
    let mut toks: Vec<String> = Vec::new();
    let (subj, plural) = noun_phrase(rng, None);
    // noun_phrase may already include article in lower-case; handle capitalisation later
    toks.extend(subj);
    if !toks.is_empty() && toks[0] == "the" {
        toks[0] = "The".to_string();
