        for _ in 0..adv_count { toks.push(choose(rng, ADVERBS).to_string()); }
    }
    if rng.gen_bool(0.45) {
        let (obj, _) = noun_phrase(rng, Some(rng.gen_bool(0.6)));
        toks.extend(obj);
    }
    while toks.len() < 4 {
        toks.push(choose(rng, ADVERBS).to_string());
    }
    if let Some(first) = toks.first_mut() {
        let mut chars = first.chars();
        if let Some(f) = chars.next() {
            *first = f.to_uppercase().collect::<String>() + chars.as_str();
        }
    }
    format!("{}.", toks.join(" "))
}

pub fn generate_sentences(number: u64) -> String {
    let mut rng = rand::thread_rng();
    let mut out = Vec::new();
    // cap to a sane loop for absurd values is handled by caller expectations;
    // generate exactly `number` sentences
    for _ in 0..number {
        out.push(generate_sentence(&mut rng));
    }
    out.join(" ")
}
RS"}

