use crossterm::style::Color;
use unicode_width::UnicodeWidthChar;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Fg { Reset, Green, Red }

#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Style {
    pub fg: Fg,
    pub bold: bool,
    pub dim: bool,
    pub italic: bool,
    pub underline: bool,
}
impl Style {
    pub const DEFAULT: Style = Style { fg: Fg::Reset, bold: false, dim: false, italic: false, underline: false };
    pub fn ansi_fg(&self) -> Option<Color> {
        match self.fg { Fg::Reset => None, Fg::Green => Some(Color::AnsiValue(2)), Fg::Red => Some(Color::AnsiValue(1)) }
    }
}

#[derive(Clone, PartialEq, Debug)]
pub struct Cell {
    pub text: String,
    pub style: Style,
    pub skip: bool,
}
impl Cell {
    pub fn blank() -> Self { Cell { text: " ".to_string(), style: Style::DEFAULT, skip: false } }
}

#[derive(Clone)]
pub struct Buffer {
    pub width: u16,
    pub height: u16,
    pub cells: Vec<Cell>,
}
impl Buffer {
    pub fn new(width: u16, height: u16) -> Self {
        Buffer { width, height, cells: vec![Cell::blank(); width as usize * height as usize] }
    }
    fn idx(&self, x: u16, y: u16) -> Option<usize> {
        if x < self.width && y < self.height { Some(y as usize * self.width as usize + x as usize) } else { None }
    }
    pub fn set_string(&mut self, mut x: u16, y: u16, text: &str, style: Style) {
        if y >= self.height { return; }
        for ch in text.chars() {
            let w = UnicodeWidthChar::width(ch).unwrap_or(0);
            if w == 0 { continue; }
            if x >= self.width { break; }
            if let Some(i) = self.idx(x, y) {
                self.cells[i] = Cell { text: ch.to_string(), style, skip: false };
            }
            if w == 2 {
                if let Some(i) = self.idx(x + 1, y) {
                    self.cells[i] = Cell { text: " ".to_string(), style, skip: true };
                }
            }
            x = x.saturating_add(w as u16);
            if x >= self.width { break; }
        }
    }
    pub fn set_cell_char(&mut self, x: u16, y: u16, ch: char, style: Style) {
        let w = UnicodeWidthChar::width(ch).unwrap_or(0);
        if w == 0 || y >= self.height || x >= self.width { return; }
        if let Some(i) = self.idx(x, y) {
            self.cells[i] = Cell { text: ch.to_string(), style, skip: false };
        }
        if w == 2 {
            if let Some(i) = self.idx(x + 1, y) {
                self.cells[i] = Cell { text: " ".to_string(), style, skip: true };
            }
        }
    }
}
