use crate::cli::Config;
use crate::generate;
use crate::render::{Buffer, Fg, Style};
use chrono::Utc;
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use crossterm::terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
use crossterm::{execute, ExecutableCommand};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::{self, IsTerminal, Write};
use std::time::{Duration, Instant};
use unicode_width::UnicodeWidthChar;

#[derive(Clone)]
struct Entry {
    ch: char,
    sec: u64,
    correct: bool,
}

pub struct App {
    cfg: Config,
    prompt: String,
    prompt_chars: Vec<char>,
    entries: Vec<Entry>,
    done: bool,
    started: bool,
    start: Option<Instant>,
    stats_secs: u64,
    has_stats_secs: bool,
    wpm_raw: f64,
    accuracy_final: f64,
    // SD tracking (see mechanism): buckets pushed when a correct char arrives in a new second
    sd_current_sec: Option<u64>,
    sd_baseline: i64,
    sd_counts: Vec<f64>,
    process_start: Instant,
}

impl App {
    fn new(cfg: Config) -> Self {
        let prompt = if let Some(p) = &cfg.prompt {
            p.clone()
        } else if cfg.full_sentences.is_some() {
            generate::generate_sentences(cfg.full_sentences.unwrap())
        } else {
            generate::generate_words(&cfg.language, cfg.number_of_words)
        };
        let mut app = App {
            cfg,
            prompt: prompt.clone(),
            prompt_chars: prompt.chars().collect(),
            entries: Vec::new(),
            done: false,
            started: false,
            start: None,
            stats_secs: 1,
            has_stats_secs: false,
            wpm_raw: 0.0,
            accuracy_final: 0.0,
            sd_current_sec: None,
            sd_baseline: 0,
            sd_counts: Vec::new(),
            process_start: Instant::now(),
        };
        app.reset_done_initial();
        app
    }

    fn reset_done_initial(&mut self) {
        self.done = self.prompt_chars.is_empty() || self.cfg.number_of_secs == Some(0);
    }

    fn reset_state(&mut self) {
        self.entries.clear();
        self.started = false;
        self.start = None;
        self.stats_secs = 1;
        self.has_stats_secs = false;
        self.wpm_raw = 0.0;
        self.accuracy_final = 0.0;
        self.sd_current_sec = None;
        self.sd_baseline = 0;
        self.sd_counts.clear();
        self.reset_done_initial();
    }

    fn retry(&mut self) {
        self.reset_state();
    }

    fn new_prompt(&mut self) {
        self.prompt = if self.cfg.full_sentences.is_some() {
            generate::generate_sentences(self.cfg.full_sentences.unwrap())
        } else {
            generate::generate_words(&self.cfg.language, self.cfg.number_of_words)
        };
        self.prompt_chars = self.prompt.chars().collect();
        self.reset_state();
    }

    fn correct_count(&self) -> usize {
        self.entries.iter().filter(|e| e.correct).count()
    }

    fn type_char(&mut self, c: char) {
        if self.done {
            return;
        }
        if !self.started {
            self.started = true;
            self.start = Some(Instant::now());
        }
        let elapsed = self.start.map(|s| s.elapsed()).unwrap_or(Duration::ZERO);
        let sec = elapsed.as_secs();
        let pos = self.entries.len();
        let correct = self.prompt_chars.get(pos).copied() == Some(c);
        if correct {
            let correct_before = self.correct_count() as i64;
            match self.sd_current_sec {
                None => {
                    self.sd_current_sec = Some(sec);
                    self.sd_baseline = correct_before;
                }
                Some(cs) if cs != sec => {
                    let bucket = correct_before - self.sd_baseline;
                    if bucket > 0 {
                        self.sd_counts.push(bucket as f64);
                    }
                    self.sd_baseline = correct_before;
                    self.sd_current_sec = Some(sec);
                }
                _ => {}
            }
        }
        self.entries.push(Entry { ch: c, sec, correct });
        if correct {
            self.stats_secs = sec + 1;
            self.has_stats_secs = true;
            self.wpm_raw = self.correct_count() as f64 * 12.0 / self.stats_secs as f64;
        }
        if self.entries.len() == self.prompt_chars.len() && !self.prompt_chars.is_empty() {
            let el = self.start.map(|s| s.elapsed()).unwrap_or(Duration::ZERO);
            self.complete(el);
        }
    }

    fn backspace(&mut self) {
        if self.done {
            return;
        }
        if self.entries.pop().is_some() {
            // wpm is recomputed against the seconds recorded at the last correct char
            self.wpm_raw = self.correct_count() as f64 * 12.0 / self.stats_secs as f64;
            if self.correct_count() == 0 && !self.has_stats_secs {
                self.wpm_raw = 0.0;
            }
        }
    }

    fn std_dev(&self) -> f64 {
        if self.sd_counts.is_empty() {
            return 0.0;
        }
        let n = self.sd_counts.len() as f64;
        let mean = self.sd_counts.iter().sum::<f64>() / n;
        let var = self.sd_counts.iter().map(|x| (x - mean) * (x - mean)).sum::<f64>() / n;
        var.sqrt()
    }

    fn complete(&mut self, elapsed: Duration) {
        if self.done {
            return;
        }
        self.done = true;
        self.accuracy_final = if self.entries.is_empty() {
            f64::NAN
        } else {
            (self.correct_count() as f64 / self.entries.len() as f64 * 100.0).round()
        };
        self.log_results(elapsed);
    }

    fn log_results(&self, elapsed: Duration) {
        let Some(mut dir) = dirs::config_dir() else { return };
        dir.push("thokr");
        let log_path = dir.join("log.csv");
        let _ = std::fs::create_dir_all(&dir);
        let exists = log_path.exists();
        let mut file = match OpenOptions::new().create(true).append(true).open(&log_path) {
            Ok(f) => f,
            Err(_) => return,
        };
        if !exists {
            if writeln!(file, "date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev").is_err() { return; }
        }
        let date = Utc::now().format("%a %b %d %H:%M:%S %Y");
        let num_secs = match self.cfg.number_of_secs {
            Some(s) => format!("{:.2}", s as f64),
            None => String::new(),
        };
        let wpm = fmt_f64(self.wpm_raw.ceil());
        let acc = fmt_f64(self.accuracy_final);
        let _ = writeln!(
            file,
            "{},{},{},{:.2},{},{},{:.2}",
            date,
            self.cfg.number_of_words,
            num_secs,
            elapsed.as_secs_f64(),
            wpm,
            acc,
            self.std_dev()
        );
    }

    fn on_tick_timeout(&mut self) {
        if self.done || !self.started {
            return;
        }
        if let (Some(limit), Some(start)) = (self.cfg.number_of_secs, self.start) {
            let el = start.elapsed();
            if el.as_secs_f64() >= limit as f64 {
                self.complete(el);
            }
        }
    }
}

fn fmt_f64(v: f64) -> String {
    if v.is_nan() {
        "NaN".to_string()
    } else if v.is_infinite() {
        if v > 0.0 { "inf".to_string() } else { "-inf".to_string() }
    } else {
        // Rust's Display for f64 prints integral floats without a decimal point
        format!("{}", v)
    }
}

// ----- prompt wrapping -----

#[derive(Clone)]
struct DispCell {
    idx: usize,
    ch: char,
    width: u16,
}

fn char_width(c: char) -> u16 {
    UnicodeWidthChar::width(c).unwrap_or(0) as u16
}

fn wrap_prompt(prompt: &[char], width: u16) -> Vec<Vec<DispCell>> {
    if width == 0 {
        return Vec::new();
    }
    let mut lines: Vec<Vec<DispCell>> = Vec::new();
    let mut current: Vec<DispCell> = Vec::new();
    let mut cur_w: u16 = 0;
    let mut pending_spaces: Vec<usize> = Vec::new();

    let mut place_in_current = |current: &mut Vec<DispCell>, cur_w: &mut u16, idx: usize, ch: char| {
        let w = char_width(ch);
        if w == 0 { return; }
        current.push(DispCell { idx, ch, width: w });
        *cur_w = cur_w.saturating_add(w);
    };

    // tokenise into words (non-space runs)
    let mut i = 0usize;
    while i < prompt.len() {
        if prompt[i] == ' ' {
            pending_spaces.push(i);
            i += 1;
            continue;
        }
        // a word
        let start = i;
        while i < prompt.len() && prompt[i] != ' ' {
            i += 1;
        }
        let word = &prompt[start..i];
        let word_w: u16 = word.iter().map(|c| char_width(*c)).sum();
        if current.is_empty() {
            pending_spaces.clear();
            // place, breaking long words
            for (off, ch) in word.iter().enumerate() {
                let idx = start + off;
                let w = char_width(*ch);
                if w == 0 { continue; }
                if cur_w + w > width {
                    if !current.is_empty() {
                        lines.push(std::mem::take(&mut current));
                        cur_w = 0;
                    }
                    if w > width { continue; }
                }
                place_in_current(&mut current, &mut cur_w, idx, *ch);
            }
        } else if cur_w + (pending_spaces.len() as u16) + word_w <= width {
            for sidx in pending_spaces.drain(..) {
                place_in_current(&mut current, &mut cur_w, sidx, ' ');
            }
            for (off, ch) in word.iter().enumerate() {
                place_in_current(&mut current, &mut cur_w, start + off, *ch);
            }
        } else {
            // wrap to a new line
            lines.push(std::mem::take(&mut current));
            cur_w = 0;
            pending_spaces.clear();
            for (off, ch) in word.iter().enumerate() {
                let idx = start + off;
                let w = char_width(*ch);
                if w == 0 { continue; }
                if cur_w + w > width {
                    if !current.is_empty() {
                        lines.push(std::mem::take(&mut current));
                        cur_w = 0;
                    }
                    if w > width { continue; }
                }
                place_in_current(&mut current, &mut cur_w, idx, *ch);
            }
        }
        pending_spaces.clear();
        // note: spaces are collected at the top of the next iterations; drain above
        // needs pending handling, so re-collect is done by main loop (spaces pushed there)
        // (pending_spaces was cleared after use; spaces after the word are added next loop)
        let _ = start;
    }
    // trailing spaces: displayed if they fit on the current line
    if !current.is_empty() {
        for sidx in pending_spaces {
            if cur_w + 1 <= width {
                place_in_current(&mut current, &mut cur_w, sidx, ' ');
            } else {
                break;
            }
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    lines
}

fn plain_wrap(text: &str, width: u16) -> Vec<String> {
    let chars: Vec<char> = text.chars().collect();
    let wrapped = wrap_prompt(&chars, width);
    wrapped
        .iter()
        .map(|line| line.iter().map(|c| c.ch).collect::<String>())
        .collect()
}

// ----- drawing -----

fn centred_x(total: u16, content: u16) -> u16 {
    if content >= total { 0 } else { (total - content + 1) / 2 }
}

impl App {
    fn draw(&self, width: u16, height: u16) -> Buffer {
        let mut buf = Buffer::new(width, height);
        if width == 0 || height == 0 {
            return buf;
        }
        if self.done {
            self.draw_results(&mut buf);
        } else {
            self.draw_test(&mut buf);
        }
        buf
    }

    fn draw_test(&self, buf: &mut Buffer) {
        let (width, height) = (buf.width, buf.height);
        let content_w = width.saturating_sub(10);
        let lines = wrap_prompt(&self.prompt_chars, content_w);
        let l = lines.len() as i32;
        let top = ((height as i32) / 2 - l / 2 - 1).max(0) as u16;
        if let Some(limit) = self.cfg.number_of_secs {
            let remaining = if let (true, Some(start)) = (self.started, self.start) {
                (limit as f64 - start.elapsed().as_secs_f64()).max(0.0)
            } else {
                limit as f64
            };
            let text = format!("{:.1}", remaining);
            let x = centred_x(width, text.chars().count() as u16);
            buf.set_string(x, top, &text, Style { fg: Fg::Reset, bold: true, dim: true, italic: false, underline: false });
        }
        let y0 = if self.cfg.number_of_secs.is_some() { top.saturating_add(2) } else { top };
        let single = lines.len() == 1;
        for (li, line) in lines.iter().enumerate() {
            let y = y0.saturating_add(li as u16);
            if y >= height { break; }
            let line_w: u16 = line.iter().map(|c| c.width).sum();
            let mut x = if single { centred_x(width, line_w) } else { 5 };
            for cell in line {
                let idx = cell.idx;
                let style = if idx < self.entries.len() {
                    if self.entries[idx].correct {
                        Style { fg: Fg::Green, bold: true, dim: false, italic: false, underline: false }
                    } else {
                        Style { fg: Fg::Red, bold: true, dim: false, italic: false, underline: false }
                    }
                } else if idx == self.entries.len() {
                    Style { fg: Fg::Reset, bold: true, dim: true, italic: false, underline: true }
                } else {
                    Style { fg: Fg::Reset, bold: true, dim: true, italic: false, underline: false }
                };
                buf.set_cell_char(x, y, cell.ch, style);
                x = x.saturating_add(cell.width);
            }
        }
    }

    fn graph_points(&self) -> Vec<(f64, f64)> {
        let mut buckets: BTreeMap<u64, u64> = BTreeMap::new();
        for e in &self.entries {
            if e.correct {
                *buckets.entry(e.sec).or_insert(0) += 1;
            }
        }
        let mut cum: u64 = 0;
        let mut pts = Vec::new();
        for (sec, count) in buckets {
            cum += count;
            let x = (sec + 1) as f64;
            let yv = cum as f64 * 12.0 / x;
            pts.push((x, yv));
        }
        pts
    }

    fn draw_results(&self, buf: &mut Buffer) {
        let (width, height) = (buf.width, buf.height);
        if height < 6 || width < 12 {
            // still try to draw the essentials with saturating positions
        }
        let points = self.graph_points();
        let max_y = points.iter().map(|p| p.1).fold(0.0f64, f64::max);
        let top_label = format!("{:.0}", max_y);
        let label_len = top_label.chars().count() as u16;
        let axis_x = 5 + label_len;
        let graph_x = axis_x + 1;
        let chart_right = width.saturating_sub(5); // exclusive
        let axis_label_y = height.saturating_sub(8);
        let axis_y = height.saturating_sub(7);
        let xlabels_y = height.saturating_sub(6);
        let info_y = height.saturating_sub(5);
        let footer_y = height.saturating_sub(3);
        let bold = Style { fg: Fg::Reset, bold: true, dim: false, italic: false, underline: false };
        let plain = Style::DEFAULT;

        // ---- graph (braille) ----
        let graph_w = chart_right.saturating_sub(graph_x);
        let graph_h = axis_label_y.saturating_sub(2);
        if graph_w > 0 && graph_h > 0 && max_y > 0.0 && !points.is_empty() {
            let dot_w = graph_w as usize * 2;
            let dot_h = graph_h as usize * 4;
            let mut dots = vec![vec![false; dot_w]; dot_h];
            let d = self.stats_secs as f64;
            let map = |p: &(f64, f64)| -> (f64, f64) {
                let dx = if d > 1.0 { (p.0 - 1.0) / (d - 1.0) * (dot_w as f64 - 1.0) } else { 0.0 };
                let dy_bottom = p.1 / max_y * (dot_h as f64 - 1.0);
                let dy = dot_h as f64 - 1.0 - dy_bottom;
                (dx, dy)
            };
            let set_dot = |dots: &mut Vec<Vec<bool>>, x: f64, y: f64| {
                let xi = x.round() as i32;
                let yi = y.round() as i32;
                if xi >= 0 && yi >= 0 && (xi as usize) < dot_w && (yi as usize) < dot_h {
                    dots[yi as usize][xi as usize] = true;
                }
            };
            if points.len() == 1 {
                let (x, y) = map(&points[0]);
                set_dot(&mut dots, x, y);
            } else {
                for pair in points.windows(2) {
                    let (x1, y1) = map(&pair[0]);
                    let (x2, y2) = map(&pair[1]);
                    let steps = ((x2 - x1).abs().max((y2 - y1).abs())).ceil() as i32;
                    if steps <= 0 {
                        set_dot(&mut dots, x1, y1);
                    } else {
                        for s in 0..=steps {
                            let t = s as f64 / steps as f64;
                            set_dot(&mut dots, x1 + (x2 - x1) * t, y1 + (y2 - y1) * t);
                        }
                    }
                }
            }
            for cy in 0..graph_h as usize {
                for cx in 0..graph_w as usize {
                    let mut bits: u8 = 0;
                    // braille dot positions: (col,row_in_cell)
                    let pos = [(0usize, 0usize, 0x01u8), (0, 1, 0x02), (0, 2, 0x04), (1, 0, 0x08), (1, 1, 0x10), (1, 2, 0x20), (0, 3, 0x40), (1, 3, 0x80)];
                    for (dc, dr, bit) in pos {
                        let dx = cx * 2 + dc;
                        let dy = cy * 4 + dr;
                        if dx < dot_w && dy < dot_h && dots[dy][dx] {
                            bits |= bit;
                        }
                    }
                    if bits != 0 {
                        let ch = char::from_u32(0x2800 + bits as u32).unwrap_or(' ');
                        buf.set_cell_char(graph_x + cx as u16, 2 + cy as u16, ch, plain);
                    }
                }
            }
        }

        // ---- axes, labels, titles ----
        buf.set_string(5, 2, &top_label, bold);
        buf.set_string(graph_x, 2, "wpm", plain);
        if axis_label_y >= 2 {
            buf.set_string(5, axis_label_y, "0", bold);
            for yy in 2..=axis_label_y {
                buf.set_cell_char(axis_x, yy, '│', plain);
            }
            let secs = "seconds";
            if chart_right as usize >= secs.len() {
                buf.set_string(chart_right - secs.len() as u16, axis_label_y, secs, plain);
            }
        }
        if axis_y >= 2 || height >= 7 {
            buf.set_cell_char(axis_x, axis_y, '└', plain);
            let mut x = graph_x;
            while x < chart_right {
                buf.set_cell_char(x, axis_y, '─', plain);
                x += 1;
            }
        }
        buf.set_string(axis_x, xlabels_y, "1", bold);
        let right = format!("{:.2}", self.stats_secs as f64);
        if chart_right as usize >= right.len() {
            buf.set_string(chart_right - right.len() as u16, xlabels_y, &right, bold);
        }

        // ---- info line ----
        let wpm_disp = fmt_f64(self.wpm_raw.ceil());
        let acc_disp = fmt_f64(self.accuracy_final);
        let info = format!("{} wpm   {}% acc   {:.2} sd", wpm_disp, acc_disp, self.std_dev());
        let content_w = width.saturating_sub(10);
        let info_lines = plain_wrap(&info, content_w);
        if let Some(first) = info_lines.first() {
            let lw = first.chars().count() as u16;
            let x = if info_lines.len() == 1 {
                5 + centred_x(content_w, lw).min(content_w.saturating_sub(lw))
            } else {
                5
            };
            // centred_x above is relative; compute directly for tidiness:
            let x = if info_lines.len() == 1 && content_w >= lw {
                5 + (content_w - lw + 1) / 2
            } else { x };
            buf.set_string(x, info_y, first, bold);
        }

        // ---- footer ----
        let footer = "(r)etry / (n)ew / (esc)ape";
        let footer_lines = plain_wrap(footer, content_w);
        if let Some(first) = footer_lines.first() {
            buf.set_string(5, footer_y, first, Style { fg: Fg::Reset, bold: false, dim: false, italic: true, underline: false });
        }
    }
}

pub fn run_app(cfg: Config) -> Result<i32, io::Error> {
    let mut app = App::new(cfg);
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let result = event_loop(&mut app, &mut stdout);
    let _ = disable_raw_mode();
    let _ = stdout.execute(LeaveAlternateScreen);
    let _ = stdout.execute(crossterm::cursor::Show);
    let _ = stdout.flush();
    result
}

fn event_loop(app: &mut App, stdout: &mut io::Stdout) -> Result<i32, io::Error> {
    let mut renderer = Renderer { prev: None, force: true };
    let mut next_tick = Instant::now() + Duration::from_millis(100);
    loop {
        let (w, h) = crossterm::terminal::size()?;
        let buf = app.draw(w, h);
        renderer.draw(stdout, &buf)?;
        // decide poll timeout
        let timeout = if !app.done && app.started && app.cfg.number_of_secs.is_some() {
            let now = Instant::now();
            if next_tick > now { next_tick - now } else { Duration::ZERO }
        } else {
            Duration::from_secs(3600)
        };
        let mut exit = false;
        if event::poll(timeout)? {
            match event::read()? {
                Event::Key(key) => {
                    if key.kind != event::KeyEventKind::Release {
                        if handle_key(app, key) {
                            exit = true;
                        }
                    }
                }
                Event::Resize(_, _) => {
                    renderer.force = true;
                }
                _ => {}
            }
        }
        if exit {
            return Ok(0);
        }
        // tick processing (100ms boundaries from loop start)
        let now = Instant::now();
        let mut ticked = false;
        while next_tick <= now {
            next_tick += Duration::from_millis(100);
            ticked = true;
            if next_tick > now + Duration::from_millis(1000) {
                next_tick = now + Duration::from_millis(100);
            }
        }
        if ticked {
            app.on_tick_timeout();
        }
    }
}

fn handle_key(app: &mut App, key: KeyEvent) -> bool {
    // returns true to exit
    match key.code {
        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
        KeyCode::Esc => return true,
        KeyCode::Left => {
            app.retry();
        }
        KeyCode::Right => {
            app.new_prompt();
        }
        KeyCode::Backspace => {
            if !app.done {
                app.backspace();
            }
        }
        KeyCode::Char(c) => {
            if app.done {
                match c {
                    'r' => app.retry(),
                    'n' => app.new_prompt(),
                    _ => {}
                }
            } else {
                app.type_char(c);
            }
        }
        _ => {}
    }
    false
}

struct Renderer {
    prev: Option<Buffer>,
    force: bool,
}

impl Renderer {
    fn draw(&mut self, stdout: &mut io::Stdout, buf: &Buffer) -> Result<(), io::Error> {
        let resized = match &self.prev {
            Some(p) => p.width != buf.width || p.height != buf.height,
            None => true,
        };
        let force = self.force || resized;
        let mut out: Vec<u8> = Vec::new();
        if resized && self.prev.is_some() {
            // clear the (new) screen area like a terminal resize redraw
            out.extend_from_slice(b"\x1b[2J");
        }
        let mut cur_style: Option<Style> = None;
        let mut cur_pos: Option<(u16, u16)> = None;
        let mut wrote = false;
        for yy in 0..buf.height {
            for xx in 0..buf.width {
                let idx = yy as usize * buf.width as usize + xx as usize;
                let cell = &buf.cells[idx];
                let changed = force || match &self.prev {
                    Some(p) if p.width == buf.width && p.height == buf.height => p.cells[idx] != *cell,
                    _ => *cell != crate::render::Cell::blank(),
                };
                if !changed || cell.skip {
                    if cell.skip {
                        // wide-char placeholder: cursor position becomes unknown
                        // (it is handled by the preceding wide char)
                    }
                    continue;
                }
                if cur_pos != Some((xx, yy)) {
                    out.extend_from_slice(format!("\x1b[{};{}H", yy + 1, xx + 1).as_bytes());
                }
                if cur_style != Some(cell.style) {
                    out.extend_from_slice(b"\x1b[0m");
                    if let Some(fg) = cell.style.ansi_fg() {
                        let code = match fg { crossterm::style::Color::AnsiValue(v) => v, _ => 0 };
                        out.extend_from_slice(format!("\x1b[38;5;{}m", code).as_bytes());
                    }
                    if cell.style.bold { out.extend_from_slice(b"\x1b[1m"); }
                    if cell.style.dim { out.extend_from_slice(b"\x1b[2m"); }
                    if cell.style.italic { out.extend_from_slice(b"\x1b[3m"); }
                    if cell.style.underline { out.extend_from_slice(b"\x1b[4m"); }
                    cur_style = Some(cell.style);
                }
                out.extend_from_slice(cell.text.as_bytes());
                wrote = true;
                let w = UnicodeWidthChar::width(cell.text.chars().next().unwrap_or(' ')).unwrap_or(1) as u16;
                if xx + w >= buf.width {
                    cur_pos = None;
                } else {
                    cur_pos = Some((xx + w, yy));
                }
            }
        }
        if wrote {
            out.extend_from_slice(b"\x1b[39m\x1b[49m\x1b[0m\x1b[?25l");
        }
        stdout.write_all(&out)?;
        stdout.flush()?;
        self.prev = Some(buf.clone());
        self.force = false;
        Ok(())
    }
}

pub fn check_stdout_is_terminal() -> bool {
    io::stdout().is_terminal()
}
