import pty,os,time,select,fcntl,termios,struct,shutil
def run(binpath, actions):
    home="/tmp/rawhome"; shutil.rmtree(home,ignore_errors=True); os.makedirs(home)
    pid,fd=pty.fork()
    if pid==0:
        fcntl.ioctl(1, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
        os.environ["TERM"]="xterm-256color"; os.environ["HOME"]=home; os.environ.pop("XDG_CONFIG_HOME",None)
        os.execv(binpath,[binpath,"-p","hello world"])
    def drain(t=0.4):
        d=b""; end=time.time()+t
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.03)
            if r:
                try: x=os.read(fd,65536)
                except: break
                d+=x
        return d
    chunks=[]
    chunks.append(("initial",drain()))
    for a in actions:
        os.write(fd,a); chunks.append((a,drain(0.3)))
    try: os.waitpid(pid,0)
    except: pass
    return chunks
