import pty,os,time,select,fcntl,termios,struct,shutil,signal
def run(binpath, seqs):
    home="/tmp/exithome"; shutil.rmtree(home,ignore_errors=True); os.makedirs(home)
    pid,fd=pty.fork()
    if pid==0:
        fcntl.ioctl(1, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
        os.environ["TERM"]="xterm-256color"; os.environ["HOME"]=home
        os.execv(binpath,[binpath,"-p","ab"])
    def drain(t=0.3):
        d=b""; end=time.time()+t
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.02)
            if r:
                try: d+=os.read(fd,65536)
                except: break
        return d
    drain()
    out=b""
    for s in seqs:
        try: os.write(fd,s)
        except: pass
        out+=drain(0.25)
    status=None
    p,st=os.waitpid(pid,os.WNOHANG)
    if p: status=os.waitstatus_to_exitcode(st)
    else:
        try: os.kill(pid,signal.SIGKILL); os.waitpid(pid,0)
        except: pass
    return status,out[-80:]
