import pathlib
p=pathlib.Path("src/app.rs"); t=p.read_text()
# add log_num_words field
t=t.replace("    sd_counts: Vec<f64>,\n}", "    sd_counts: Vec<f64>,\n    log_num_words: u64,\n}")
t=t.replace("""        let mut app = App {
            cfg,
            prompt: prompt.clone(),""", """        let initial_sentence_prompt = cfg.prompt.is_none() && cfg.full_sentences.is_some();
        let mut app = App {
            log_num_words: if cfg.full_sentences.is_some() { 0 } else { cfg.number_of_words },
            cfg,
            prompt: prompt.clone(),""")
# after app creation, set sentence count -- insert before app.reset_done_initial();
t=t.replace("""        app.reset_done_initial();
        app""", """        if initial_sentence_prompt {
            app.log_num_words = app.prompt.split_whitespace().count() as u64;
        }
        app.reset_done_initial();
        app""")
# new_prompt: set if sentences
t=t.replace("""        self.prompt_chars = self.prompt.chars().collect();
        self.reset_state();
    }

    fn correct_count""", """        self.prompt_chars = self.prompt.chars().collect();
        if self.cfg.full_sentences.is_some() {
            self.log_num_words = self.prompt.split_whitespace().count() as u64;
        }
        self.reset_state();
    }

    fn correct_count""")
# log uses log_num_words
t=t.replace("            self.cfg.number_of_words,\n            num_secs,", "            self.log_num_words,\n            num_secs,")
p.write_text(t)
