python3 - << 'PY'
import subprocess,time
def trial(bp,wait):
    subprocess.run(["tmux","kill-server"],stderr=subprocess.DEVNULL); time.sleep(0.06)
    subprocess.run(["tmux","new-session","-d","-s","t","-x","80","-y","24",f'{bp} -p "abcdefghij" -s 3']); time.sleep(0.35)
    subprocess.run(["tmux","send-keys","-t","t","-l","a"]); time.sleep(wait)
    r=subprocess.run(["tmux","capture-pane","-t","t","-p"],capture_output=True,text=True)
    print(bp,wait,[l.strip() for l in r.stdout.splitlines() if l.strip()])
    subprocess.run(["tmux","kill-server"],stderr=subprocess.DEVNULL)
for w in [0.27,0.53,0.99,2.4]:
    trial("./executable",w); trial("./target/release/executable",w)
PY"}

