{"command":"python3 - << 'PY'
import subprocess,time
def trial(bp):
    subprocess.run(["tmux","kill-server"],stderr=subprocess.DEVNULL); time.sleep(0.07)
    subprocess.run(["tmux","new-session","-d","-s","t","-x","80","-y","24",f'{bp} -p "hello world this is a longer prompt with many words to wrap around the screen test prompt" -s 9']); time.sleep(0.4)
    r=subprocess.run(["tmux","capture-pane","-t","t","-p"],capture_output=True,text=True)
    print(bp)
    for i,l in enumerate(r.stdout.splitlines()):
        if l.strip(): print(i,repr(l.rstrip()))
    subprocess.run(["tmux","kill-server"],stderr=subprocess.DEVNULL)
trial("./executable"); trial("./target/release/executable")
# also single line timed at different heights
for h in [10,15,30]:
    for bp in ["./executable","./target/release/executable"]:
        subprocess.run(["tmux","kill-server"],stderr=subprocess.DEVNULL); time.sleep(0.05)
        subprocess.run(["tmux","new-session","-d","-s","t","-x","80","-y",str(h),f'{bp} -p "hello world" -s 9']); time.sleep(0.3)
        r=subprocess.run(["tmux","capture-pane","-t","t","-p"],capture_output=True,text=True)
        print(h,bp,[ (i,l.strip()) for i,l in enumerate(r.stdout.splitlines()) if l.strip()])
PY"}

